import{_ as a,o as t,c as r,a3 as s}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"1.6 不同种物料控制结构（拓展阅读）","description":"","frontmatter":{"translationSource":{"title":"1.6 不同种物料控制结构（拓展阅读）","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=36dBqcBcCjyVD88enH50kC","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/control-structures-for-different-materials"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/control-structures-for-different-materials"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/control-structures-for-different-materials"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/control-structures-for-different-materials"}]]},"headers":[],"relativePath":"zh/control-structures-for-different-materials.md","filePath":"zh/page-36dBqcBcCjyVD88enH50kC.md"}'),n={name:"zh/control-structures-for-different-materials.md"};function o(i,e,d,p,l,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<div class="logistics-content"><h1 id="_1-6-不同种物料控制结构-拓展阅读" tabindex="-1">1.6 不同种物料控制结构（拓展阅读） <a class="header-anchor" href="#_1-6-不同种物料控制结构-拓展阅读" aria-label="Permalink to &quot;1\\.6 不同种物料控制结构（拓展阅读）&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-23. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>36dBqcBcCjyVD88enH50kC</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=36dBqcBcCjyVD88enH50kC" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>可参考<a href="/endfield-skydoc/zh/logistics-principles-and-frontier-research">物流原理与一些名词</a></p><p><span id="source-block-TYzFDvSHTuUTc3BHvqUUUH"></span></p><h2 id="混管混带阻塞控制" tabindex="-1">混管混带阻塞控制 <a class="header-anchor" href="#混管混带阻塞控制" aria-label="Permalink to &quot;混管混带阻塞控制&quot;">​</a></h2><p>暂时借用discord@radio的系列教材<a href="https://beta.enka.network/endfield/aic/?id=V1x4c2j5p4P9W1" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=V1x4c2j5p4P9W1</a></p><details><summary>radio系列教材</summary><p>part 2 is sprinkler switches <a href="https://beta.enka.network/endfield/aic/?id=B4d8c6K5T2r4z5" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=B4d8c6K5T2r4z5</a></p><p>part 3 is zero-waste transmuters <a href="https://beta.enka.network/endfield/aic/?id=P7T0p6n0D2f6p6" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=P7T0p6n0D2f6p6</a></p><p>part 4 is compound stuffs <a href="https://beta.enka.network/endfield/aic/?id=M5B0F5J9s8C0t5" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=M5B0F5J9s8C0t5</a></p></details><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a07e9d2ecedd83cf.q90-0c951c6e3f5c6628.webp" alt="16 不同种物料控制结构（拓展阅读）"></p><p>从左到右，依次翻译原图说明：</p><p><strong>① 两路同步通行</strong></p><p>这种结构也叫锁、过滤器、锁存器或开关。先用汇流器把两条线合为一路，再用分流器分开，并用物品准入口指定每种物品走哪条输出线。正常输送时，两路物品交替通过，各占一半的通行机会，输送节奏也随之同步。任意一路堵塞，另一路也会停下来。图中的储存箱装满时，就能看到这一现象。多数物流控制装置都以这种结构为基础。</p><p><strong>② 优先汇流</strong></p><p>在优先门的汇流器前，让其中一路通过分流器直接接入。这个分流器与其余输入线路的铺设先后，决定了该路的输入优先级。没有分流器的各路优先级相同。带分流器的这一路，如果分流器比其他输入线先放，就优先通行；如果后放，就让其他线先走。图中的分流器最后放置，因此另一路优先。</p><p>两路同时有货时，优先门总是先放行高优先级线路。低优先级线路只有在高优先级线路出现空档时才能通过。如果高优先级线路的传送带或管道持续满载，低优先级线路就完全无法通行。</p><p><strong>③ 低优先级线路补位</strong></p><p>高优先级线路断续供料时，低优先级线路会补上空档。上游产出速率低于传送带或管道的最大输送速率，就会自然留下空档。也可以通过主动阻断输送或限流来制造空档。</p><p><strong>④ 多输出设施的输出优先级</strong></p><p>前面的例子用分流器影响汇流器优先接收哪一路。这个例子里，一台设施有多个输出口，汇流器会影响物料优先从哪个口送出。把汇流器直接接在其中一个输出口上，这一路的优先级是升是降，取决于它与其他输出线路的相对权重。</p><p>计算权重时，从输出口沿线路往下游数，直到最近的另一台设施。沿途每个物流元件算一段，每段连续的传送带或管道也算一段，无论长短。图中接汇流器的线路权重为 2，另一路为 1，因此接汇流器的这一路优先级较低。这台设施只有一路满载输入，高优先级线路足以接走全部来料，所以物料全部从高优先级线路送出，低优先级线路没有输出。</p><p><strong>⑤ 高优先级输出线堵塞时，物料改走低优先级线</strong></p><p>当高优先级输出线间歇性堵塞时，堵塞期间的物料会改从低优先级线送出。图中在低优先级线上多加了一个物流元件，使这条线的权重增至 3。这样，即使高优先级线的权重也增至 2，它仍然优先输出。</p><p>如果接有优先汇流器的线路与另一路权重相同，就按接入顺序决定输出优先级：先接入的线路优先。</p><p><span id="source-block-XBevRAqYsJ9tUuAGpz0Jqi"></span></p><h2 id="断电反应池" tabindex="-1">断电反应池 <a class="header-anchor" href="#断电反应池" aria-label="Permalink to &quot;断电反应池&quot;">​</a></h2><p>参考<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production">1.5智能最大毛产</a><a href="/endfield-skydoc/zh/some-simpler-adaptive-setups">较简单的零浪费装置</a>等</p><p>反应池有5个槽可以容纳固体或者液体，先放4个杂物，再让需要控制的固体或液体穿过反应池，可以形成回路或者直接过路，看需求。同时让待检测的固体或液体穿过反应池。如果待检测的东西完全堵住了，需要控制的固体或液体就进不了反应池，形成控制。</p><p>主要用于<strong>固体控制液体或液体控制固体</strong>。同相的直接用混管混带就行</p><p>当然事实上供电也行就是浪费，关闭反应池不行</p><p><span id="source-block-F8E9BNZJZ9KMebEI51DQLA"></span></p><h2 id="流量复制" tabindex="-1">流量复制 <a class="header-anchor" href="#流量复制" aria-label="Permalink to &quot;流量复制&quot;">​</a></h2><p>参考<a href="/endfield-skydoc/zh/some-simpler-adaptive-setups">较简单的零浪费装置</a>中灌拆附近的部分，利用两次取反，让检测路的流量控制输出的流量（完全相同复制）</p></div>',1)])])}const k=a(n,[["render",o]]);export{h as __pageData,k as default};
